ST.xhtml:p:
Ton_RealTimeCalibrate();
g_ZAxisRealTimeCalibrate.ENABLE := g_bRealTimeCalibrate;
R_tringRealTimeCaliStart(CLk := g_bProcessStartForRealTimeCalibrate);
IF R_tringRealTimeCaliStart.Q AND g_bRealTimeCalibrate THEN
  Ton_RealTimeCalibrate.IN := FALSE;
  nRealTimeState := 5;
  g_bProcessStartForRealTimeCalibrate := FALSE;
END_IF;

R_tringRealTimeCaliStop(CLK := g_bProcessEndForRealTimeCalibrate);
IF R_tringRealTimeCaliStop.Q THEN
  Ton_RealTimeCalibrate.IN := FALSE;
  g_bRealTimeCAlibrateStarting := FALSE;
  g_bProcessEndForRealTimeCalibrate := FALSE;
  nRealTimeState := 0;
END_IF;

CASE nRealTimeState OF 
  0:
    nRealTimeState := 0;
  5:
    Ton_RealTimeCalibrate.PT := LREAL_TO_TIME(g_dRealTimeCalibration);  
    Ton_RealTimeCalibrate.IN := TRUE;
    IF Ton_RealTimeCalibrate.Q THEN
      g_bRealTimeCAlibrateStarting := TRUE;
      Ton_RealTimeCalibrate.IN := FALSE;
      nRealTimeState := 10;
    END_IF;
  10:
    IF NOT g_bRealTimeCAlibrateStarting THEN
      nRealTimeState := 5;
    END_IF;
END_CASE;
IF g_bPlcResetBuffer THEN
  g_bProcessStartForRealTimeCalibrate := FALSE;
  g_bProcessEndForRealTimeCalibrate := FALSE;
  nRealTimeState := 0;
  Ton_RealTimeCalibrate.IN := FALSE;
END_IF;
